import {detect,signature,distance} from './vision.js';
const $=s=>document.querySelector(s), el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const db=await fetch('data.json').then(r=>{if(!r.ok)throw Error('DB 로드 실패');return r.json()});
$('#dataInfo').textContent=`DB 확인 ${db.checkedAt.slice(0,10)} · ${db.pokemon.length}종/폼 · ${Object.keys(db.moves).length}개 기술`;
const storage=await new Promise((resolve,reject)=>{const r=indexedDB.open('go-lens-private',1);r.onupgradeneeded=()=>r.result.createObjectStore('cards',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}).catch(()=>null);
let cards=[],selected=null,cancel=false,busy=false,videoURL=null,cal=null,calpoints=null,job=0;
try{cal=JSON.parse(localStorage.getItem('go-lens-cal')||'null')}catch{}
function status(s){$('#status').textContent=s}
async function transaction(mode,fn){if(!storage)throw Error('기기 저장소를 사용할 수 없습니다.');return new Promise((resolve,reject)=>{const t=storage.transaction('cards',mode),req=fn(t.objectStore('cards'));let value;req.onsuccess=()=>value=req.result;t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function save(card){try{await transaction('readwrite',s=>s.put(card));}catch{status('기기 저장에 실패했습니다. 탭을 닫기 전에 백업을 내보내세요.')}const i=cards.findIndex(x=>x.id===card.id);if(i<0)cards.push(card);else cards[i]=card;render()}
function render(){const root=$('#cards');root.replaceChildren();$('#count').textContent=cards.length;$('#empty').hidden=!!cards.length;for(const c of [...cards].reverse()){const b=el('button','card');b.type='button';const img=el('img');img.src=c.image;img.alt=c.demo?'예제 조사 화면':`조사 화면 ${c.time?.toFixed(1)||0}초`;b.append(img);const body=el('div','cardbody');body.append(el('span','cardtag',c.demo?'DEMO · 예제':c.confirmed?'REVIEWED · 교정 저장됨':'NEEDS REVIEW · 확인 필요'),el('h3',null,db.pokemon.find(p=>p.id===c.species)?.name||'포켓몬을 선택해 주세요'),el('p',null,`${c.time?.toFixed(1)||0}초 · ${c.confidence||'수동 저장'}`));const line=el('div','ivline');line.append(el('strong',null,c.iv?.every(Number.isInteger)?c.iv.join(' / '):'IV 판독 대기'),el('span',null,'분석 ↗'));body.append(line);b.append(body);b.onclick=()=>open(c);root.append(b)}}
try{cards=await transaction('readonly',s=>s.getAll());render()}catch{status('기기 저장소 사용 불가 · 현재 탭에서는 분석과 백업이 가능합니다.')}
const worker=new Worker('worker.js',{type:'module'}),pending=new Map();worker.onmessage=({data})=>{const p=pending.get(data.id);if(p){pending.delete(data.id);clearTimeout(p.timer);data.error?p.reject(Error(data.error)):p.resolve(data.result)}};worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('분석 작업을 실행하지 못했습니다. 페이지를 새로 열어 주세요.'))}pending.clear()};
function calculate(data){return new Promise((resolve,reject)=>{const id=++job,timer=setTimeout(()=>{pending.delete(id);reject(Error('계산 시간이 초과되었습니다. 다시 시도해 주세요.'))},60000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,db,...data})})}
function options(select,items,placeholder){select.replaceChildren();if(placeholder){const o=el('option',null,placeholder);o.value='';select.append(o)}for(const [value,label] of items){const o=el('option',null,label);o.value=value;select.append(o)}}
function speciesOptions(query='',value=''){const list=db.pokemon.filter(p=>`${p.name} ${p.id} ${p.dex}`.toLowerCase().includes(query.toLowerCase()));options($('#species'),list.map(p=>[p.id,`${p.name} · #${p.dex}`]),'종·폼을 직접 선택하세요');if(list.some(p=>p.id===value))$('#species').value=value;}
function moveOptions(p,fast='',charged=''){options($('#fast'),(p?.fast||[]).map(k=>[k,`${k} · ${db.moves[k].type}`]),'실제 보유 기술 선택');options($('#charged'),(p?.charged||[]).map(k=>[k,`${k} · ${db.moves[k].type}`]),'실제 보유 기술 선택');$('#fast').value=fast;$('#charged').value=charged;$('#shadow').disabled=!!p?.mega;if(p?.mega)$('#shadow').checked=false;}
const types=['normal','fire','water','electric','grass','ice','fighting','poison','ground','flying','psychic','bug','rock','ghost','dragon','dark','steel','fairy'];options($('#type1'),types.map(t=>[t,t]),'중립 (타입 없음)');options($('#type2'),types.map(t=>[t,t]),'없음');
let imageObj=null;async function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('이미지를 읽을 수 없습니다.'));i.src=src})}
async function open(c){selected=c;calpoints=null;$('#search').value='';speciesOptions('',c.species);moveOptions(db.pokemon.find(p=>p.id===c.species),c.fast,c.charged);['atk','def','hp'].forEach((k,i)=>$('#'+k).value=c.iv?.[i]??'');$('#level').value=c.level||'';$('#maxlevel').value=c.max||50;$('#shadow').checked=c.shadow||false;$('#bossdef').value=c.target?.defense||200;$('#type1').value=c.target?.types?.[0]||'';$('#type2').value=c.target?.types?.[1]||'';$('#error').textContent='';$('#results').replaceChildren();$('#calhelp').textContent=c.confidence||'수동으로 IV를 입력하거나 좌표를 보정하세요.';$('#detail').showModal();imageObj=await loadImage(c.image);draw();if(c.confirmed)analyze(false)}
function draw(){const cv=$('#shot');cv.width=imageObj.naturalWidth;cv.height=imageObj.naturalHeight;const ctx=cv.getContext('2d');ctx.drawImage(imageObj,0,0);if(calpoints){ctx.fillStyle='#00ddff';for(const [x,y] of calpoints){ctx.beginPath();ctx.arc(x*cv.width,y*cv.height,7,0,Math.PI*2);ctx.fill()}}}
$('#search').oninput=e=>speciesOptions(e.target.value,$('#species').value);$('#species').onchange=()=>{moveOptions(db.pokemon.find(p=>p.id===$('#species').value));$('#results').replaceChildren()};
$('#calibrate').onclick=()=>{calpoints=[];$('#calhelp').textContent='1/5 · 첫 막대의 왼쪽 시작점을 클릭하세요 (빈 부분 포함 전체 길이 기준).';draw()};
$('#shot').onclick=e=>{if(!calpoints)return;const cv=$('#shot'),r=cv.getBoundingClientRect(),scale=Math.min(r.width/cv.width,r.height/cv.height),dw=cv.width*scale,dh=cv.height*scale,x=(e.clientX-r.left-(r.width-dw)/2)/dw,y=(e.clientY-r.top-(r.height-dh)/2)/dh;if(x<0||x>1||y<0||y>1)return;calpoints.push([x,y]);draw();const prompts=['','첫 막대의 오른쪽 끝을 클릭하세요 (15 IV 길이).','공격 막대 중앙을 클릭하세요.','방어 막대 중앙을 클릭하세요.','HP 막대 중앙을 클릭하세요.'];if(calpoints.length<5){$('#calhelp').textContent=`${calpoints.length+1}/5 · ${prompts[calpoints.length]}`;return}const [a,b,c,d,h]=calpoints;if(b[0]-a[0]<.1||!(c[1]<d[1]&&d[1]<h[1])){$('#calhelp').textContent='좌표 순서가 올바르지 않습니다. 보정을 다시 시작하세요.';calpoints=null;return}cal={x0:a[0],x1:b[0],ys:[c[1],d[1],h[1]]};try{localStorage.setItem('go-lens-cal',JSON.stringify(cal))}catch{}calpoints=null;draw();const result=detect(cv.getContext('2d').getImageData(0,0,cv.width,cv.height),cal);['atk','def','hp'].forEach((k,i)=>$('#'+k).value=result.iv[i]);$('#calhelp').textContent='좌표 보정 완료. 판독한 IV를 확인하고 저장하세요. 같은 화면 배치에서만 유효합니다.'};
function metric(title,value,sub,right){const n=el('div','metric'),a=el('div');a.append(el('small',null,title),el('strong',null,value),el('small',null,sub));n.append(a);if(right){const b=el('div','right');b.append(el('strong',null,right[0]),el('small',null,right[1]));n.append(b)}return n}
async function analyze(persist=true){const c=selected;$('#error').textContent='';try{const p=db.pokemon.find(p=>p.id===$('#species').value);if(!p)throw Error('종과 폼을 선택하세요.');const inputs=['atk','def','hp'].map(k=>$('#'+k).value);if(inputs.some(x=>x===''))throw Error('IV 세 항목을 모두 확인해 주세요.');const iv=inputs.map(Number);if(iv.some(x=>!Number.isInteger(x)||x<0||x>15))throw Error('IV는 0–15 정수로 입력하세요.');const level=$('#level').value===''?null:Number($('#level').value),max=Number($('#maxlevel').value),shadow=$('#shadow').checked,target={defense:Number($('#bossdef').value),types:[$('#type1').value,$('#type2').value].filter(Boolean)};if(level!==null&&(!Number.isFinite(level)||level<1||level>51||level*2%1))throw Error('레벨은 1–51, 0.5 단위로 입력하세요.');if(!Number.isFinite(target.defense)||target.defense<1||target.defense>1000)throw Error('보스 방어력은 1–1000 범위입니다.');if(target.types.length===2&&target.types[0]===target.types[1])throw Error('보스 타입은 서로 다르게 선택하세요.');if(shadow&&p.mega)throw Error('그림자와 메가 폼은 동시에 적용할 수 없습니다.');const data={p,iv,level,max,shadow,target,fast:$('#fast').value,charged:$('#charged').value};$('#analyze').disabled=true;$('#analyze').textContent='4,096개 조합 비교 중…';const r=await calculate(data);if(selected?.id!==c.id)return;if(persist)await save({...c,species:p.id,iv,level,max,shadow,target,fast:data.fast,charged:data.charged,confirmed:true});const root=$('#results');root.replaceChildren();root.append(metric('개체값 IV',r.iv.toFixed(2)+'%',iv.join(' / '),r.current?[`CP ${r.current.cp}`,`현재 레벨 ${level}`]:null));root.append(el('h3','resulttitle',`PvP 스탯곱 · 최대 레벨 ${max} · IV 하한 0`));if(p.mega)root.append(el('p',null,'메가 폼의 PvP 리그 계산은 제공하지 않습니다.'));else r.leagues.forEach((s,i)=>{root.append(s?metric(['슈퍼리그 · CP 1,500','하이퍼리그 · CP 2,500','마스터리그 · 무제한'][i],s.percent.toFixed(3)+'%',`레벨 ${s.level} · CP ${s.cp} · HP ${s.h}`,['#'+s.rank.toLocaleString(),'/ 4,096 조합']):el('p',null,'레벨 1에서도 CP 상한을 초과합니다.'))});root.append(el('p','micro','스탯곱 % = 내 최적 스탯곱 ÷ 같은 종·폼 최상위 스탯곱 × 100. 동점은 같은 순위. 현재 레벨과 무관한 최적 육성 기준이며 그림자 피해 보정은 스탯곱에 적용하지 않습니다.'));root.append(el('h3','resulttitle','레이드 · 간이 사이클 DPS 모델'));if(r.raid){root.append(metric('개인 모델 등급',r.raid.tier,`사이클 DPS ${r.raid.dps.toFixed(2)} · 기준 대비 ${r.raid.percent.toFixed(1)}%`));root.append(el('p','micro',`비교 기준: DB 전체 종·폼의 레벨 40, 15/15/15, 일반/그림자/메가, 가능한 기술 조합 중 최대 DPS ${r.raid.top.toFixed(2)}. S ≥95%, A ≥85%, B ≥70%, C ≥55%, D <55%. 보스 방어 ${target.defense}, 타입 ${target.types.join('/')||'중립'}. 현재 개체가 40레벨을 넘으면 100%를 초과할 수 있습니다.`));}else root.append(el('p',null,'레이드 분석에는 현재 레벨과 보유 노말·스페셜 기술을 모두 선택하세요.'));root.append(el('p','micro','이 등급은 공식/실전 레이드 티어가 아닙니다. STAB 1.2, 타입 상성, 그림자 공격 1.2, 메가 기본 능력치를 반영합니다. 피격 에너지·생존시간·회피·파티 보너스·날씨·프렌드·보스 기술·특수 효과는 미반영입니다. 정확한 레이드 시뮬레이터로 검증하세요.'));}catch(e){$('#error').textContent=e.message}finally{$('#analyze').disabled=false;$('#analyze').textContent='교정 저장 · 분석하기 ↗'}}
$('#analyze').onclick=()=>analyze();
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('#download').onclick=()=>{const a=el('a');a.href=selected.image;a.download=`go-lens-${selected.id}.jpg`;a.click()};
$('#delete').onclick=async()=>{if(!selected||!confirm('이 카드와 스크린샷을 기기에서 삭제할까요?'))return;try{await transaction('readwrite',s=>s.delete(selected.id))}catch{}cards=cards.filter(c=>c.id!==selected.id);$('#detail').close();render()};
$('#clear').onclick=async()=>{if(busy){status('분석을 중지한 뒤 삭제하세요.');return}if(!confirm('이 기기의 모든 분석 카드와 보정 좌표를 삭제할까요? 내보낸 백업은 별도로 남습니다.'))return;try{await transaction('readwrite',s=>s.clear())}catch{}cards=[];cal=null;try{localStorage.removeItem('go-lens-cal')}catch{}render();status('기기에 저장된 카드와 보정 좌표를 삭제했습니다.')};
$('#export').onclick=()=>download(JSON.stringify({schema:1,exportedAt:new Date().toISOString(),cards}),`go-lens-${new Date().toISOString().slice(0,10)}.json`,'application/json');
$('#restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error('백업은 100MB 이하로 선택하세요.');const b=JSON.parse(await f.text());if(b.schema!==1||!Array.isArray(b.cards)||b.cards.length>500)throw Error('지원하지 않는 백업입니다.');for(const c of b.cards){if(typeof c.id!=='string'||c.id.length>100||typeof c.image!=='string'||!/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(c.image)||c.image.length>8e6)throw Error('백업 카드의 이미지 형식이 잘못되었습니다.');if(c.iv&&(!Array.isArray(c.iv)||c.iv.length!==3||c.iv.some(n=>!Number.isInteger(n)||n<0||n>15)))throw Error('잘못된 IV가 포함되어 있습니다.');if(c.species&&!db.pokemon.some(p=>p.id===c.species))throw Error('현재 DB에 없는 종·폼이 있습니다.')}for(const c of b.cards)await save(c);status(`${b.cards.length}개 카드 복원 완료`)}catch(e){status(e.message)}finally{e.target.value=''}};
const canvas=document.createElement('canvas');function frame(source){const w=source.videoWidth||source.naturalWidth,h=source.videoHeight||source.naturalHeight;if(!w||!h)throw Error('영상/이미지 프레임을 읽지 못했습니다.');canvas.width=Math.min(w,720);canvas.height=Math.round(h*canvas.width/w);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,canvas.width,canvas.height);return ctx.getImageData(0,0,canvas.width,canvas.height)}
async function addFrame(source,time=0,force=false){const pixels=frame(source),r=detect(pixels,cal),sig=signature(pixels);if(!force&&!r.candidate)return false;if(!force&&cards.slice(-30).some(c=>c.sig&&distance(c.sig,sig)<.12))return false;await save({id:crypto.randomUUID(),image:canvas.toDataURL('image/jpeg',.84),time,iv:r.candidate?r.iv:null,confidence:force?'수동 저장 · 확인 필요':r.confidence,sig,confirmed:false});return true}
function waitVideo(v,event,action){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>finish(Error('영상을 읽는 시간이 초과되었습니다. MP4 또는 스크린샷으로 다시 시도하세요.')),20000),ok=()=>finish(),bad=()=>finish(Error('이 브라우저가 영상 코덱을 재생하지 못합니다. H.264 MP4 또는 스크린샷을 사용하세요.'));function finish(err){clearTimeout(timer);v.removeEventListener(event,ok);v.removeEventListener('error',bad);err?reject(err):resolve()}v.addEventListener(event,ok,{once:true});v.addEventListener('error',bad,{once:true});action()})}
$('#stop').onclick=()=>{cancel=true;status('현재 프레임 처리 후 중지합니다. 저장된 카드는 유지됩니다.')};
$('#capture').onclick=async()=>{if(busy)return;try{await addFrame($('#video'),$('#video').currentTime,true);status('현재 장면을 저장했습니다. 카드를 선택해 교정하세요.')}catch(e){status(e.message)}};
async function importFiles(files){if(busy)return;busy=true;cancel=false;$('#files').disabled=true;$('#stop').hidden=false;$('#progress').hidden=false;let n=0;try{for(const file of files){if(cancel)break;if(file.type.startsWith('image/')){const url=URL.createObjectURL(file);try{const img=await loadImage(url);await addFrame(img,0,true);n++}finally{URL.revokeObjectURL(url)}continue}if(!file.type.startsWith('video/')&&!/\.(mp4|mov|m4v)$/i.test(file.name)){status('영상 또는 이미지 파일만 선택하세요.');continue}if(file.size>1024**3)throw Error('영상은 1GB 이하로 나누어 선택하세요.');if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(file);const v=$('#video');await waitVideo(v,'loadedmetadata',()=>{v.src=videoURL;v.load()});$('#videoPanel').hidden=false;if(!Number.isFinite(v.duration)||v.duration>900)throw Error('MVP는 최대 15분 영상까지 지원합니다. 짧게 나누어 주세요.');v.pause();const step=Number($('#interval').value);for(let t=.05;t<v.duration&&!cancel;t+=step){await waitVideo(v,'seeked',()=>v.currentTime=Math.min(t,v.duration-.001));if(await addFrame(v,t))n++;$('#progress').value=t/v.duration;status(`${Math.floor(t)} / ${Math.floor(v.duration)}초 확인 · 새 카드 ${n}개 · 화면을 열어 두세요.`);await new Promise(r=>setTimeout(r,0))}}status(`${cancel?'중지':'분석 완료'} · 새 카드 ${n}개. ${n?'카드에서 종과 IV를 확인하세요.':'탐지된 화면이 없으면 미리보기에서 직접 저장하거나 스크린샷을 추가하세요.'}`)}catch(e){status(e.message)}finally{busy=false;$('#files').disabled=false;$('#files').value='';$('#stop').hidden=true;$('#progress').hidden=true}}
$('#files').onchange=e=>importFiles([...e.target.files]);const drop=$('#drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');importFiles([...e.dataTransfer.files])};
$('#demo').onclick=async()=>{const cv=document.createElement('canvas');cv.width=390;cv.height=720;const c=cv.getContext('2d');c.fillStyle='#e9eee0';c.fillRect(0,0,390,720);c.fillStyle='#456347';c.font='20px sans-serif';c.fillText('DEMO / AZUMARILL',40,65);c.font='100px sans-serif';c.fillText('◎',145,240);c.fillStyle='#fffdf5';c.fillRect(28,350,334,300);c.fillStyle='#3e5c42';c.font='18px sans-serif';c.fillText('EXAMPLE · 0 / 15 / 15',48,390);['ATTACK','DEFENSE','HP'].forEach((t,i)=>{c.fillStyle='#50684a';c.font='12px sans-serif';c.fillText(t,48,428+i*60);c.fillStyle='#e3e5d9';c.fillRect(48,440+i*60,270,10);if(i){c.fillStyle='#ec9a48';c.fillRect(48,440+i*60,270,10)}});await save({id:crypto.randomUUID(),image:cv.toDataURL('image/jpeg'),demo:true,species:'azumarill',iv:[0,15,15],level:40,max:50,confirmed:true,confidence:'예제 데이터 · 실제 포켓몬 아님',time:0});status('예제 카드를 추가했습니다. 선택하면 계산 결과를 볼 수 있습니다.')};
